import Foundation

/// 一套写进机身的滤镜：614 字节载荷 + 显示信息
public struct PictCtrlPreset: Identifiable {
    public let id: String          // 1dlut 里的 id
    public let displayName: String // 界面显示的中文名
    public let desc: String        // 一句话说明
    public let cameraName: String  // 进载荷的 ASCII 名（机身菜单里显示这个）
    public let payloadBase64: String // 614 字节载荷（base64）

    public var payload: Data? { Data(base64Encoded: payloadBase64) }
}

public enum PictCtrlPresets {
    public static let all: [PictCtrlPreset] = [
        PictCtrlPreset(id: "light-film", displayName: "轻胶片", desc: "胶片味，轻微褪色", cameraName: "LIGHT-FILM",
            payloadBase64: ""),
        PictCtrlPreset(id: "mono-hard", displayName: "黑白 · 强对比", desc: "黑白，高反差", cameraName: "MONO-HARD",
            payloadBase64: ""),
        PictCtrlPreset(id: "bright-clear", displayName: "明亮通透", desc: "亮部通透，色彩干净", cameraName: "BRIGHT-CLEAR",
            payloadBase64: ""),
        PictCtrlPreset(id: "faded-soft", displayName: "柔和褪色", desc: "低饱和，柔和褪色", cameraName: "FADED-SOFT",
            payloadBase64: ""),
        PictCtrlPreset(id: "fl25-cool-mute", displayName: "胶片 · 低饱和冷调", desc: "冷调，低饱和", cameraName: "FL25-COOL",
            payloadBase64: ""),
        PictCtrlPreset(id: "fl26-warm-mute", displayName: "胶片 · 低饱和暖调", desc: "暖调，低饱和", cameraName: "FL26-WARM",
            payloadBase64: ""),
        PictCtrlPreset(id: "cinema-dark", displayName: "电影暗调", desc: "电影感，暗调", cameraName: "CINEMA-DARK",
            payloadBase64: ""),
        PictCtrlPreset(id: "soft-portrait", displayName: "柔和人像", desc: "人像，柔和低反差", cameraName: "SOFT-PORTRAIT",
            payloadBase64: ""),
    ]
}
